add(nr=711, id="10471042646282", orig_titel="Lyftstångsset TUNTURI PRO Aerobic Pump Set 20 kg",
 fakta='''Lyftstångsset TUNTURI PRO Aerobic Pump Set 20 kg. Vill du ta din styrketräning till nästa nivå hemma eller på gymmet? Då är Tunturi Pro Aerobic Pump Set precis vad du behöver! Denna professionella och högkvalitativa set är idealisk för muskelträning, styrketräning och gruppklasser. Lyftstänger, 6 viktskivor och lås – allt du behöver för ett bra träningspass! Setet innehåller: 1 lyftstång. 2 lyfthakar. 2 viktskivor på 1,25 kg. 2 viktskivor på 2,5 kg. 2 viktskivor på 5 kg. Tillverkare . Detaljer: Mått: 140 x 22 x 22 cm. Längd på lyfthandtag: 140 cm. Diameter på handtaget: 30 mm. Lastkapacitet: 60 kg. Märke Tunturi, typ Professionell utrustning, taggar Fell, Professionell utrustning, Pump, skivstångspaket, Skivstångspaket - 30mm, Tunturi, Velomarket. Variant Default Title, SKU 14TUSCL457''',
 titel="Lyftstångsset Tunturi Pro Aerobic Pump Set, 20 kg, 30 mm",
 seo_title="Lyftstångsset Tunturi Pro Aerobic Pump",
 meta="Tunturi Pro Aerobic Pump Set 20 kg är ett lyftstångsset med 1 lyftstång, 2 lyfthakar och 6 viktskivor (2 x 1,25, 2 x 2,5 och 2 x 5 kg).",
 intro="Tunturi Pro Aerobic Pump Set 20 kg är ett lyftstångsset med 1 lyftstång, 2 lyfthakar och 6 viktskivor. Lyfthandtaget är 140 cm långt med diameter 30 mm.",
 passar=["Muskelträning, styrketräning och gruppklasser, hemma eller på gymmet","Dig som vill ha lyftstång och viktskivor i ett set","Dig som vill ha ett set med skivor på 1,25, 2,5 och 5 kg"],
 spec=["Ingår: 1 lyftstång, 2 lyfthakar, 2 viktskivor på 1,25 kg, 2 viktskivor på 2,5 kg, 2 viktskivor på 5 kg","Mått: 140 x 22 x 22 cm","Längd på lyfthandtag: 140 cm","Diameter på handtaget: 30 mm","Lastkapacitet: 60 kg"],
 faq=[("Vad ingår i setet?","1 lyftstång, 2 lyfthakar och 6 viktskivor: 2 på 1,25 kg, 2 på 2,5 kg och 2 på 5 kg.")], marke=None,
 motivering="Fakta ur källan. \"Professionell och högkvalitativ\", \"idealisk\", \"allt du behöver\" och \"nästa nivå\" utelämnas. Texten nämner \"lås\" som inte finns i innehållslistan, så lås utelämnas.",
 att_bekrafta=["Beskrivningen säger \"6 viktskivor och lås\", men innehållslistan har bara lyftstång, lyfthakar och viktskivor. Ingår lås? Är \"lyfthakar\" låsen?","Titeln säger 20 kg men skivorna väger 17,5 kg tillsammans, och lyftstångens vikt anges inte. Stämmer 20 kg?","\"Lastkapacitet 60 kg\" bör kontrolleras mot datablad (säkerhetsuppgift).","Tillverkarraden är tom i källan."])

