add(nr=713, id="10472260665610", orig_titel="TUNTURI Weight Vest Pro 20kg",
 fakta='''TUNTURI Weight Vest Pro 20kg. Bär denna Tunturi viktväst om du vill intensifiera dina övningar på ett enkelt sätt. Det beror på att västen kan lyfta upp till 20 kg av din kroppsvikt. Du kan börja med maximal intensitet med full vikt, men du kanske föredrar att röra dig långsamt. Vågen är laddad med vikter på 1 kg vardera, så du kan göra västen så tung som du vill. Det är en one-size-fits-all-modell som passar alla. Du kastar viktvästen över huvudet och knyter sedan fast den ordentligt runt midjan. Fördelar med Tunturi viktväst - Justerbar Pro - 20 kg. Perfekt verktyg för träning med extra vikt. Justerbar med kardborrefäste. Vikten kan justeras med lösa vikter, var och en väger 1 kg. Enkel svart design. Vill du bära några extra kilon? Beställ då denna Tunturi viktväst nu och gör ditt träningspass ännu mer utmanande! Om Tunturi: Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Tekniska data översikt: Maximal vikt: 20 kg. Justerbar med vikter på 1 kg. vardera. One size fits all. Färg: Svart. Finns även med en maximal vikt på 30 kg. Produktkod: 14TUSCF097. Märke Tunturi, typ Extra vikter, tillbehör, taggar Extra vikter, Fell, tillbehör, Tunturi, Velomarket, Viktväst. Variant Default Title, SKU 14TUSCF097''',
 titel="Viktväst Tunturi Pro, 20 kg, svart",
 seo_title="Viktväst Tunturi Pro, 20 kg, svart",
 meta="Tunturi viktväst Pro med maximal vikt 20 kg, justerbar med lösa vikter på 1 kg vardera och kardborrefäste. En storlek, svart. Finns även med max 30 kg.",
 intro="Tunturi Weight Vest Pro är en justerbar viktväst med maximal vikt 20 kg. Vikten justeras med lösa vikter på 1 kg vardera, och västen har kardborrefäste.",
 passar=["Dig som vill träna med extra vikt","Dig som vill justera vikten i steg om 1 kg upp till 20 kg","Dig som vill ha en väst i en storlek (one size)"],
 spec=["Maximal vikt: 20 kg","Justerbar med lösa vikter på 1 kg vardera","Kardborrefäste","Storlek: one size","Färg: svart","Finns även med maximal vikt 30 kg"],
 faq=[("Finns västen med högre vikt?","Ja, den finns även med en maximal vikt på 30 kg.")], marke=None,
 motivering="Fakta ur källan. \"Intensifiera\", \"mer utmanande\", \"perfekt verktyg\", uppmaningen \"Beställ nu\" och \"passar alla\" utelämnas. Tunturis standardtext om märket används inte. Raden om hur västen tas på utelämnas (se att bekräfta).",
 att_bekrafta=["Texten säger att västen \"knyts fast runt midjan\" medan specifikationen säger kardborrefäste. Hur sitter västen?","Meningen \"Vågen är laddad med vikter på 1 kg vardera\" är sannolikt en maskinöversättning (väst, inte våg).","Det framgår inte om de 20 vikterna ingår eller om bara västen levereras. Bekräfta innehåll.","\"Kan lyfta upp till 20 kg av din kroppsvikt\" är oklart formulerat och används inte."])

add(nr=715, id="10472274133258", orig_titel="Gymnastikmatta TUNTURI Fitnessmat NBR, blå",
 fakta='''Gymnastikmatta TUNTURI Fitnessmat NBR, blå. Gillar du att träna på golvet på gymmet? Ligger du på mattan under dessa övningar? Nu kan du ta med dig din Tunturi Fitnessmatta. Det är skönt och fräscht att ha en egen matta när du gör magövningar. Du kommer att slappna av ännu mer när du gör yogaposer. Den praktiska förvaringsväskan gör att du kan rulla ihop den och ta med den. Att ha en egen träningsmatta är användbart och fräscht! Fördelar med Tunturi NBR - träningsmatta med bärväska: Använd din egen matta hemma och på gymmet. Ger mjukt stöd under magövningar och yogaklasser tack vare det tjocka materialet. Levereras med en bärväska för att ta med mattan till klassen. Beställ en Tunturi NBR Fitnessmatta och träna dina muskler på din egen matta! Om Tunturi: Må bättre varje dag. Det är Tunturis motto. Våra rötter finns i Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödsystem. Det är ett ständigt växande och uppgraderande sortiment av högkvalitativa produkter och bra garantier. Omfattande tekniska data: Material: massivt skum. Färg: blå. Storlek: 180 x 60 x 1,5 cm. Produktkod: 14TUSFU133. EAN-kod: 8717842020425. Märke Tunturi, typ Yogamattor, taggar träningsmatta, Tunturi, Velomarket, Yogamattor. Variant Default Title, SKU 14TUSFU133''',
 titel="Gymnastikmatta Tunturi Fitnessmat NBR, 180 x 60 cm, blå",
 seo_title="Gymnastikmatta Tunturi Fitnessmat NBR",
 meta="Tunturi Fitnessmat NBR är en blå gymnastikmatta på 180 x 60 x 1,5 cm i massivt skum, för golvövningar och yoga. Levereras med bärväska.",
 intro="Tunturi Fitnessmat NBR är en blå gymnastikmatta på 180 x 60 x 1,5 cm i massivt skum, för övningar på golvet. En bärväska medföljer.",
 passar=["Magövningar och yogaklasser","Dig som vill ha en egen matta hemma och på gymmet","Dig som vill kunna rulla ihop och ta med mattan i bärväska"],
 spec=["Storlek: 180 x 60 x 1,5 cm","Material: massivt skum","Färg: blå","Levereras med bärväska"],
 faq=[], marke=None,
 motivering="Fakta ur källan. Säljtexten (\"skönt och fräscht\", \"praktiska\", \"träna dina muskler\", uppmaningen att beställa) och Tunturis standardtext om märket utelämnas.",
 att_bekrafta=["Titeln och produktnamnet säger NBR, men källan anger materialet \"massivt skum\". Är det NBR-skum?","Mattan i butiken (Fitnessmat NBR, 1,5 cm) liknar produkt 722 (Tunturi NBR, 15 mm). Kontrollera att de inte är dubbletter.","Titelns typ Gymnastikmatta men produkttypen är Yogamattor."])
